import sys

def print_fibonacci_up_to_n(n):
    if n < 1:
        return

    # Start the Fibonacci sequence
    a, b = 1, 1

    # Print the first number if it's within range
    if a <= n:
        print(a)

    # Print the second number if it's within range
    if b <= n:
        print(b)

    # Generate and print subsequent Fibonacci numbers
    while True:
        next_fib = a + b
        if next_fib > n:
            break
        print(next_fib)
        a, b = b, next_fib

# Read the command line argument
if len(sys.argv) != 2:
    print("Usage: python script.py <N>")
    sys.exit(1)

try:
    n = int(sys.argv[1])
    print_fibonacci_up_to_n(n)
except ValueError:
    print("Please provide a valid integer")
    sys.exit(1)

import sys

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Check odd divisors up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <N>")
        sys.exit(1)

    try:
        N = int(sys.argv[1])
    except ValueError:
        print("Please provide a valid integer")
        sys.exit(1)

    if N < 2:
        # No primes less than 2
        return

    for num in range(2, N + 1):
        if is_prime(num):
            print(num)

if __name__ == "__main__":
    main()

