type Person struct {
	ID        int    `json:"id"`
	FirstName string `json:"first_name"`
	LastName  string `json:"last_name"`
	Email     string `json:"email"`
	Age       int    `json:"age"`
}

func main() {
	file, err := os.Open("input/input.csv")
	if err != nil {
		log.Fatal(err)
	}
	defer file.Close()

	reader := csv.NewReader(file)
	records, err := reader.ReadAll()
	if err != nil {
		log.Fatal(err)
	}

	var people []Person
	// Skip header row
	for i, record := range records {
		if i == 0 {
			continue
		}
		if len(record) < 5 {
			continue
		}

		id, err := strconv.Atoi(record[0])
		if err != nil {
			continue
		}

		firstName := record[1]
		lastName := record[2]
		email := record[3]

		birthDate, err := time.Parse("2006-01-02", record[4])
		if err != nil {
			continue
		}

		age := calculateAge(birthDate, time.Date(2025, 7, 1, 0, 0, 0, 0, time.UTC))

		people = append(people, Person{
			ID:        id,
			FirstName: firstName,
			LastName:  lastName,
			Email:     email,
			Age:       age,
		})
	}

	output, err := json.Marshal(people)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println(string(output))
}

func calculateAge(birthDate, referenceDate time.Time) int {
	age := referenceDate.Year() - birthDate.Year()

	// Adjust if birthday hasn't occurred yet this year
	if referenceDate.Month() < birthDate.Month() ||
		(referenceDate.Month() == birthDate.Month() && referenceDate.Day() < birthDate.Day()) {
		age--
	}

	return age
}
